enum Incomplete {}  enum Ready {}

struct Form<State> { fileprivate var fields: Fields }

extension Form where State == Incomplete {
    func shipping(_ a: Address) -> Form<Ready> { Form(fields: fields.with(a)) }
}
extension Form where State == Ready {
    func submit() -> Confirmation { Confirmation(fields) }   // absent while Incomplete
}

struct Form: ~Copyable {
    private var fields: Fields

    consuming func shipping(_ a: Address) -> ReadyForm {
        ReadyForm(fields: fields.with(a))
    }
}
// after form.shipping(a) the original `form` is consumed and cannot be used again

